INSERT INTO leader_bio_paragraphs (id,bio_id,ord,period,period_start_precision,period_end_precision,heading,body,version) VALUES ('836f299d-c379-5617-ac54-3b6e3cc977d9','01a1c437-b43f-7116-bd87-22313035593e',1,'[1842-07-30,1898-01-01)'::daterange,'day','year','{"en": "Origins and path to the Washington legation", "zh-Hant": "出身與出任駐美公使前"}'::jsonb,'{"en": "According to the BnF authority record, Wu Tingfang was born on 30 July 1842 in Malacca. He was called to the English bar in 1876, becoming the first Chinese barrister, and in 1897 he was appointed minister to the United States, Spain and Peru.", "zh-Hant": "據法國國家圖書館（BnF）權威記錄，伍廷芳於1842年7月30日生於馬六甲；1876年取得英國律師資格，成為首位華人大律師，1897年被任命為駐美國、西班牙與秘魯公使。"}'::jsonb,0);
