INSERT INTO leader_bio_paragraphs (id,bio_id,ord,period,period_start_precision,period_end_precision,heading,body,version) VALUES ('05ee61f7-a876-5030-a4cd-46ec4329e784','01a1b4b0-6fe9-72db-be2c-915cf61baa62',3,'[1932-01-01,1946-10-07)'::daterange,'year','day','{"en": "1932–1946: prime ministership and death", "zh-Hant": "1932至1946年：首相任內與逝世"}'::jsonb,'{"en": "In 1932, in the midst of the economic crisis, Hansson became leader of a Social Democratic minority government, and in 1933 reached the so-called crisis settlement with the Agrarian League. His government was replaced by an Agrarian League government in summer 1936, but in September that year he formed a government again. After the outbreak of the Winter War in December 1939 he formed a national coalition government, and externally Sweden’s formal, later somewhat contested neutrality was secured. He died on 6 October 1946.", "zh-Hant": "1932年經濟危機中，漢森出任社會民主黨少數政府的領導人，1933年與農民聯盟達成「危機協議」。1936年夏天其政府被農民聯盟政府取代，同年9月他再度組閣。1939年12月冬季戰爭爆發後他組成國家聯合政府，對外確保瑞典形式上、後來頗受爭議的中立。他於1946年10月6日逝世。"}'::jsonb,0);
